package com.example.dam.Screens

import androidx.compose.animation.AnimatedVisibility
import androidx.compose.animation.animateContentSize
import androidx.compose.animation.core.animateFloatAsState
import androidx.compose.animation.expandVertically
import androidx.compose.animation.fadeIn
import androidx.compose.animation.fadeOut
import androidx.compose.animation.shrinkVertically
import androidx.compose.foundation.background
import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.foundation.shape.CircleShape
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.automirrored.filled.ArrowBack
import androidx.compose.material.icons.automirrored.filled.DirectionsBike
import androidx.compose.material.icons.filled.*
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.clip
import androidx.compose.ui.draw.rotate
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.platform.LocalContext
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.text.style.TextAlign
import androidx.compose.ui.text.style.TextOverflow
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import androidx.lifecycle.viewmodel.compose.viewModel
import androidx.navigation.NavController
import com.example.dam.models.SortieResponse
import com.example.dam.ui.theme.*
import com.example.dam.utils.UserPreferences
import com.example.dam.viewmodel.MyParticipationRequestsViewModel
import java.text.SimpleDateFormat
import java.util.*

/**
 * Data class pour regrouper les demandes par sortie
 */
data class SortieWithRequests(
    val sortie: SortieResponse,
    val requests: List<MyParticipationRequestsViewModel.ParticipationWithSortie>,
    val pendingCount: Int,
    val acceptedCount: Int,
    val refusedCount: Int
)

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun AllParticipationRequestsScreen(
    navController: NavController,
    viewModel: MyParticipationRequestsViewModel = viewModel()
) {
    val context = LocalContext.current
    val token = remember { UserPreferences.getToken(context) ?: "" }
    val currentUserId = remember { UserPreferences.getUserId(context) ?: "" }

    val allRequests by viewModel.allRequests.collectAsState()
    val isLoading by viewModel.isLoading.collectAsState()
    val errorMessage by viewModel.errorMessage.collectAsState()
    val successMessage by viewModel.successMessage.collectAsState()

    // État pour les sorties expandées
    var expandedSortieIds by remember { mutableStateOf(setOf<String>()) }

    // Charger les demandes au démarrage
    LaunchedEffect(currentUserId) {
        if (currentUserId.isNotEmpty()) {
            viewModel.loadAllRequestsForUser(currentUserId)
        }
    }

    // Messages de succès
    LaunchedEffect(successMessage) {
        successMessage?.let {
            android.widget.Toast.makeText(context, it, android.widget.Toast.LENGTH_SHORT).show()
            viewModel.clearMessages()
        }
    }

    // Messages d'erreur
    LaunchedEffect(errorMessage) {
        errorMessage?.let {
            android.widget.Toast.makeText(context, it, android.widget.Toast.LENGTH_LONG).show()
            viewModel.clearMessages()
        }
    }

    // ✅ Regrouper les demandes par sortie
    val sortiesWithRequests = remember(allRequests) {
        allRequests
            .groupBy { it.sortie.id }
            .map { (_, requests) ->
                val sortie = requests.first().sortie
                SortieWithRequests(
                    sortie = sortie,
                    requests = requests.sortedByDescending { it.participation.createdAt },
                    pendingCount = requests.count { it.participation.status == "EN_ATTENTE" },
                    acceptedCount = requests.count { it.participation.status == "ACCEPTEE" },
                    refusedCount = requests.count { it.participation.status == "REFUSEE" }
                )
            }
            .sortedByDescending { it.pendingCount } // Sorties avec le plus de demandes en attente en premier
    }

    // Compter le total des demandes en attente
    val totalPending = sortiesWithRequests.sumOf { it.pendingCount }

    Scaffold(
        topBar = {
            TopAppBar(
                title = {
                    Column {
                        Text(
                            text = "Demandes de participation",
                            fontSize = 18.sp,
                            fontWeight = FontWeight.Bold,
                            color = TextPrimary
                        )
                        if (totalPending > 0) {
                            Text(
                                text = "$totalPending en attente",
                                fontSize = 12.sp,
                                color = Color(0xFFFFA500)
                            )
                        }
                    }
                },
                navigationIcon = {
                    IconButton(onClick = { navController.popBackStack() }) {
                        Icon(
                            imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                            contentDescription = "Retour",
                            tint = TextPrimary
                        )
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = BackgroundDark.copy(alpha = 0.9f),
                    titleContentColor = TextPrimary,
                    navigationIconContentColor = TextPrimary
                )
            )
        },
        containerColor = Color.Transparent
    ) { innerPadding ->
        Box(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding)
                .background(
                    Brush.verticalGradient(
                        colors = listOf(BackgroundGradientStart, BackgroundDark, BackgroundGradientEnd)
                    )
                )
        ) {
            when {
                isLoading -> {
                    Box(
                        modifier = Modifier.fillMaxSize(),
                        contentAlignment = Alignment.Center
                    ) {
                        Column(
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.spacedBy(16.dp)
                        ) {
                            CircularProgressIndicator(color = GreenAccent)
                            Text(
                                "Chargement des demandes...",
                                color = TextSecondary,
                                fontSize = 14.sp
                            )
                        }
                    }
                }

                allRequests.isEmpty() -> {
                    Column(
                        modifier = Modifier
                            .fillMaxSize()
                            .padding(32.dp),
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.Center
                    ) {
                        Icon(
                            imageVector = Icons.Default.GroupOff,
                            contentDescription = null,
                            tint = TextTertiary,
                            modifier = Modifier.size(80.dp)
                        )
                        Spacer(modifier = Modifier.height(24.dp))
                        Text(
                            text = "Aucune demande pour le moment",
                            color = TextSecondary,
                            fontSize = 16.sp,
                            textAlign = TextAlign.Center
                        )
                        Spacer(modifier = Modifier.height(8.dp))
                        Text(
                            text = "Les demandes de participation à vos sorties apparaîtront ici",
                            color = TextTertiary,
                            fontSize = 14.sp,
                            textAlign = TextAlign.Center
                        )
                    }
                }

                else -> {
                    LazyColumn(
                        modifier = Modifier.fillMaxSize(),
                        contentPadding = PaddingValues(16.dp),
                        verticalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        // Info résumé
                        item {
                            Text(
                                text = "${sortiesWithRequests.size} sortie${if (sortiesWithRequests.size > 1) "s" else ""} avec des demandes",
                                color = TextSecondary,
                                fontSize = 14.sp,
                                modifier = Modifier.padding(bottom = 8.dp)
                            )
                        }

                        // Liste des sorties avec leurs demandes
                        items(sortiesWithRequests, key = { it.sortie.id }) { sortieWithRequests ->
                            val isExpanded = expandedSortieIds.contains(sortieWithRequests.sortie.id)

                            SortieRequestsCard(
                                sortieWithRequests = sortieWithRequests,
                                isExpanded = isExpanded,
                                onToggleExpand = {
                                    expandedSortieIds = if (isExpanded) {
                                        expandedSortieIds - sortieWithRequests.sortie.id
                                    } else {
                                        expandedSortieIds + sortieWithRequests.sortie.id
                                    }
                                },
                                onNavigateToSortie = {
                                    navController.navigate("sortieDetail/${sortieWithRequests.sortie.id}")
                                },
                                onAccept = { participationId ->
                                    viewModel.acceptParticipation(
                                        participationId,
                                        sortieWithRequests.sortie.id,
                                        token,
                                        currentUserId
                                    )
                                },
                                onRefuse = { participationId ->
                                    viewModel.refuseParticipation(
                                        participationId,
                                        sortieWithRequests.sortie.id,
                                        token,
                                        currentUserId
                                    )
                                }
                            )
                        }

                        item { Spacer(modifier = Modifier.height(32.dp)) }
                    }
                }
            }
        }
    }
}

@Composable
fun SortieRequestsCard(
    sortieWithRequests: SortieWithRequests,
    isExpanded: Boolean,
    onToggleExpand: () -> Unit,
    onNavigateToSortie: () -> Unit,
    onAccept: (String) -> Unit,
    onRefuse: (String) -> Unit
) {
    val rotationAngle by animateFloatAsState(
        targetValue = if (isExpanded) 180f else 0f,
        label = "rotation"
    )

    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .animateContentSize(),
        shape = RoundedCornerShape(16.dp),
        color = CardGlass,
        shadowElevation = 4.dp
    ) {
        Column(
            modifier = Modifier.background(CardDark.copy(alpha = 0.7f))
        ) {
            // === Header de la sortie (toujours visible, cliquable pour expand) ===
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .clickable { onToggleExpand() }
                    .padding(16.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                // Icône selon le type
                Box(
                    modifier = Modifier
                        .size(50.dp)
                        .clip(RoundedCornerShape(12.dp))
                        .background(
                            when (sortieWithRequests.sortie.type) {
                                "VELO" -> Color(0xFF4CAF50).copy(alpha = 0.2f)
                                "RANDONNEE" -> Color(0xFFFF9800).copy(alpha = 0.2f)
                                else -> GreenAccent.copy(alpha = 0.2f)
                            }
                        ),
                    contentAlignment = Alignment.Center
                ) {
                    Icon(
                        imageVector = when (sortieWithRequests.sortie.type) {
                            "VELO" -> Icons.AutoMirrored.Filled.DirectionsBike
                            "RANDONNEE" -> Icons.Default.Hiking
                            else -> Icons.Default.Explore
                        },
                        contentDescription = null,
                        tint = when (sortieWithRequests.sortie.type) {
                            "VELO" -> Color(0xFF4CAF50)
                            "RANDONNEE" -> Color(0xFFFF9800)
                            else -> GreenAccent
                        },
                        modifier = Modifier.size(26.dp)
                    )
                }

                Spacer(modifier = Modifier.width(14.dp))

                Column(modifier = Modifier.weight(1f)) {
                    Text(
                        text = sortieWithRequests.sortie.titre,
                        color = TextPrimary,
                        fontSize = 16.sp,
                        fontWeight = FontWeight.Bold,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis
                    )
                    Text(
                        text = sortieWithRequests.sortie.date,
                        color = TextSecondary,
                        fontSize = 13.sp
                    )

                    // Badges de comptage
                    Row(
                        modifier = Modifier.padding(top = 6.dp),
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        if (sortieWithRequests.pendingCount > 0) {
                            CountBadge(
                                count = sortieWithRequests.pendingCount,
                                label = "en attente",
                                color = Color(0xFFFFA500)
                            )
                        }
                        if (sortieWithRequests.acceptedCount > 0) {
                            CountBadge(
                                count = sortieWithRequests.acceptedCount,
                                label = "acceptée${if (sortieWithRequests.acceptedCount > 1) "s" else ""}",
                                color = SuccessGreen
                            )
                        }
                        if (sortieWithRequests.refusedCount > 0) {
                            CountBadge(
                                count = sortieWithRequests.refusedCount,
                                label = "refusée${if (sortieWithRequests.refusedCount > 1) "s" else ""}",
                                color = ErrorRed
                            )
                        }
                    }
                }

                // Flèche d'expansion
                Icon(
                    imageVector = Icons.Default.KeyboardArrowDown,
                    contentDescription = if (isExpanded) "Réduire" else "Développer",
                    tint = GreenAccent,
                    modifier = Modifier
                        .size(28.dp)
                        .rotate(rotationAngle)
                )
            }

            // === Liste des demandes (visible seulement si expanded) ===
            AnimatedVisibility(
                visible = isExpanded,
                enter = expandVertically() + fadeIn(),
                exit = shrinkVertically() + fadeOut()
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .background(CardDark.copy(alpha = 0.3f))
                        .padding(horizontal = 16.dp, vertical = 12.dp),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    // Bouton voir détails sortie
                    OutlinedButton(
                        onClick = onNavigateToSortie,
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(10.dp),
                        colors = ButtonDefaults.outlinedButtonColors(contentColor = GreenAccent)
                    ) {
                        Icon(Icons.Default.Visibility, null, modifier = Modifier.size(18.dp))
                        Spacer(Modifier.width(8.dp))
                        Text("Voir les détails de la sortie")
                    }

                    HorizontalDivider(color = BorderColor, thickness = 0.5.dp)

                    // Liste des demandes
                    sortieWithRequests.requests.forEach { request ->
                        ParticipantRequestItem(
                            request = request,
                            onAccept = { onAccept(request.participation._id) },
                            onRefuse = { onRefuse(request.participation._id) }
                        )
                    }
                }
            }
        }
    }
}

@Composable
private fun CountBadge(
    count: Int,
    label: String,
    color: Color
) {
    Surface(
        shape = RoundedCornerShape(12.dp),
        color = color.copy(alpha = 0.15f)
    ) {
        Text(
            text = "$count $label",
            color = color,
            fontSize = 11.sp,
            fontWeight = FontWeight.Medium,
            modifier = Modifier.padding(horizontal = 8.dp, vertical = 3.dp)
        )
    }
}

@Composable
fun ParticipantRequestItem(
    request: MyParticipationRequestsViewModel.ParticipationWithSortie,
    onAccept: () -> Unit,
    onRefuse: () -> Unit
) {
    fun formatDate(dateString: String): String {
        return try {
            val input = SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'", Locale.getDefault()).apply {
                timeZone = TimeZone.getTimeZone("UTC")
            }
            val output = SimpleDateFormat("dd MMM à HH:mm", Locale.getDefault())
            val date = input.parse(dateString)
            date?.let { output.format(it) } ?: dateString
        } catch (e: Exception) {
            dateString
        }
    }

    Surface(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(12.dp),
        color = CardDark.copy(alpha = 0.5f)
    ) {
        Column(
            modifier = Modifier.padding(12.dp)
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                verticalAlignment = Alignment.CenterVertically
            ) {
                // Avatar
                Box(
                    modifier = Modifier
                        .size(40.dp)
                        .clip(CircleShape)
                        .background(Brush.linearGradient(listOf(GreenAccent, TealAccent))),
                    contentAlignment = Alignment.Center
                ) {
                    Text(
                        text = request.participation.userId.email.first().uppercase(),
                        color = Color.White,
                        fontSize = 16.sp,
                        fontWeight = FontWeight.Bold
                    )
                }

                Spacer(modifier = Modifier.width(12.dp))

                Column(modifier = Modifier.weight(1f)) {
                    Text(
                        text = request.participation.userId.email.substringBefore("@"),
                        color = TextPrimary,
                        fontSize = 14.sp,
                        fontWeight = FontWeight.SemiBold
                    )
                    Text(
                        text = formatDate(request.participation.createdAt),
                        color = TextTertiary,
                        fontSize = 11.sp
                    )
                }

                StatusBadge(status = request.participation.status)
            }

            // Actions pour les demandes en attente
            if (request.participation.status == "EN_ATTENTE") {
                Spacer(modifier = Modifier.height(12.dp))
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    OutlinedButton(
                        onClick = onRefuse,
                        modifier = Modifier.weight(1f),
                        colors = ButtonDefaults.outlinedButtonColors(contentColor = ErrorRed),
                        shape = RoundedCornerShape(10.dp),
                        contentPadding = PaddingValues(vertical = 8.dp)
                    ) {
                        Icon(Icons.Default.Close, null, modifier = Modifier.size(16.dp))
                        Spacer(Modifier.width(4.dp))
                        Text("Refuser", fontSize = 13.sp)
                    }

                    Button(
                        onClick = onAccept,
                        modifier = Modifier.weight(1f),
                        colors = ButtonDefaults.buttonColors(containerColor = GreenAccent),
                        shape = RoundedCornerShape(10.dp),
                        contentPadding = PaddingValues(vertical = 8.dp)
                    ) {
                        Icon(Icons.Default.Check, null, modifier = Modifier.size(16.dp), tint = Color.White)
                        Spacer(Modifier.width(4.dp))
                        Text("Accepter", color = Color.White, fontSize = 13.sp)
                    }
                }
            }
        }
    }
}

package com.example.dam.models

import com.google.gson.annotations.SerializedName

/**
 * Modèle pour les sorties sauvegardées
 */
data class SavedSortieResponse(
    @SerializedName("_id") val id: String,
    @SerializedName("sortie") val sortie: SortieInfo,
    @SerializedName("savedAt") val savedAt: String
)

data class SaveSortieRequest(
    @SerializedName("sortieId") val sortieId: String
)

data class SaveSortieResponse(
    @SerializedName("success") val success: Boolean,
    @SerializedName("message") val message: String
)

data class RemoveSavedSortieResponse(
    @SerializedName("success") val success: Boolean,
    @SerializedName("message") val message: String
)

package com.example.dam.repository

import android.util.Log
import com.example.dam.models.SaveSortieRequest
import com.example.dam.models.SavedSortieResponse
import com.example.dam.remote.RetrofitInstance
import com.example.dam.utils.Result

/**
 * Repository pour gérer les sorties sauvegardées
 */
class SavedSortiesRepository {
    private val api = RetrofitInstance.adventureApi
    private val TAG = "SavedSortiesRepository"

    /**
     * Récupère toutes les sorties sauvegardées
     */
    suspend fun getSavedSorties(token: String): Result<List<SavedSortieResponse>> {
        return try {
            val response = api.getSavedSorties("Bearer $token")
            if (response.isSuccessful && response.body() != null) {
                Log.d(TAG, "✅ Successfully fetched ${response.body()!!.size} saved sorties")
                Result.Success(response.body()!!)
            } else {
                val errorMsg = "Error ${response.code()}: ${response.message()}"
                Log.e(TAG, "❌ $errorMsg")
                Result.Error(errorMsg)
            }
        } catch (e: Exception) {
            Log.e(TAG, "❌ Exception: ${e.message}", e)
            Result.Failure(e)
        }
    }

    /**
     * Sauvegarde une sortie
     */
    suspend fun saveSortie(token: String, sortieId: String): Result<String> {
        return try {
            val request = SaveSortieRequest(sortieId)
            val response = api.saveSortie("Bearer $token", request)
            if (response.isSuccessful && response.body() != null) {
                val message = response.body()!!.message
                Log.d(TAG, "✅ $message")
                Result.Success(message)
            } else {
                val errorMsg = "Error ${response.code()}: ${response.message()}"
                Log.e(TAG, "❌ $errorMsg")
                Result.Error(errorMsg)
            }
        } catch (e: Exception) {
            Log.e(TAG, "❌ Exception: ${e.message}", e)
            Result.Failure(e)
        }
    }

    /**
     * Supprime une sortie sauvegardée
     */
    suspend fun removeSavedSortie(token: String, sortieId: String): Result<String> {
        return try {
            val response = api.removeSavedSortie("Bearer $token", sortieId)
            if (response.isSuccessful && response.body() != null) {
                val message = response.body()!!.message
                Log.d(TAG, "✅ $message")
                Result.Success(message)
            } else {
                val errorMsg = "Error ${response.code()}: ${response.message()}"
                Log.e(TAG, "❌ $errorMsg")
                Result.Error(errorMsg)
            }
        } catch (e: Exception) {
            Log.e(TAG, "❌ Exception: ${e.message}", e)
            Result.Failure(e)
        }
    }

    /**
     * Vérifie si une sortie est sauvegardée
     */
    suspend fun checkIfSortieSaved(token: String, sortieId: String): Result<Boolean> {
        return try {
            val response = api.checkIfSortieSaved("Bearer $token", sortieId)
            if (response.isSuccessful && response.body() != null) {
                val isSaved = response.body()!!["saved"] ?: false
                Log.d(TAG, "✅ Sortie $sortieId is saved: $isSaved")
                Result.Success(isSaved)
            } else {
                val errorMsg = "Error ${response.code()}: ${response.message()}"
                Log.e(TAG, "❌ $errorMsg")
                Result.Error(errorMsg)
            }
        } catch (e: Exception) {
            Log.e(TAG, "❌ Exception: ${e.message}", e)
            Result.Failure(e)
        }
    }
}

package com.example.dam.viewmodel

import android.util.Log
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.dam.models.*
import com.example.dam.remote.ORSRequest
import com.example.dam.remote.OpenRouteServiceInstance
import com.example.dam.repository.AdventureRepository
import com.example.dam.utils.JwtHelper
import com.example.dam.utils.Result
import com.google.android.gms.maps.model.LatLng
import kotlinx.coroutines.Job
import kotlinx.coroutines.delay
import kotlinx.coroutines.launch
import java.io.File

class CreateAdventureViewModel : ViewModel() {
    private val repo = AdventureRepository()

    var title by mutableStateOf("")
    var description by mutableStateOf("")
    var date by mutableStateOf("")
    var activityType by mutableStateOf("")
    var capacity by mutableStateOf("")
    var includeCamping by mutableStateOf(false)

    var campingName by mutableStateOf("")
    var campingLocation by mutableStateOf("")
    var campingPrice by mutableStateOf("")
    var campingStart by mutableStateOf("")
    var campingEnd by mutableStateOf("")

    var startLatLng by mutableStateOf<LatLng?>(null)
    var endLatLng by mutableStateOf<LatLng?>(null)
    var startAddress by mutableStateOf("")
    var endAddress by mutableStateOf("")
    var distance by mutableStateOf("")
    var footTime by mutableStateOf("")
    var bikeTime by mutableStateOf("")
    var calculating by mutableStateOf(false)
    var createResult by mutableStateOf<Result<String>?>(null)

    var polylinePoints by mutableStateOf<List<LatLng>>(emptyList())

    var editingStart by mutableStateOf(true)
    var isSearchingAddress by mutableStateOf(false)

    private var geocodeJob: Job? = null
    private var addressSearchJob: Job? = null

    fun setEditingPoint(isStart: Boolean) {
        editingStart = isStart
    }

    fun clearStartPoint() {
        startLatLng = null
        startAddress = ""
        polylinePoints = emptyList()
        distance = ""
        footTime = ""
        bikeTime = ""
    }

    fun clearEndPoint() {
        endLatLng = null
        endAddress = ""
        polylinePoints = emptyList()
        distance = ""
        footTime = ""
        bikeTime = ""
    }

    fun onMapClick(point: LatLng) {
        if (editingStart) {
            startLatLng = point
            startAddress = "Chargement..."

            geocodeJob?.cancel()
            geocodeJob = viewModelScope.launch {
                delay(300)
                startAddress = repo.reverseGeocode(point)
            }
        } else {
            endLatLng = point
            endAddress = "Chargement..."

            geocodeJob?.cancel()
            geocodeJob = viewModelScope.launch {
                delay(300)
                endAddress = repo.reverseGeocode(point)
            }
        }
    }

    fun searchAddress(address: String, isStart: Boolean) {
        if (address.isEmpty()) return

        isSearchingAddress = true
        addressSearchJob?.cancel()
        addressSearchJob = viewModelScope.launch {
            try {
                delay(500)
                val latLng = repo.geocodeAddress(address)
                if (latLng != null) {
                    if (isStart) {
                        startLatLng = latLng
                        startAddress = address
                    } else {
                        endLatLng = latLng
                        endAddress = address
                    }
                } else {
                    if (isStart) startAddress = "Adresse introuvable"
                    else endAddress = "Adresse introuvable"
                }
            } finally {
                isSearchingAddress = false
            }
        }
    }

    fun calculateRoute() {
        val s = startLatLng ?: return
        val e = endLatLng ?: return

        if (calculating) return

        calculating = true
        polylinePoints = emptyList()

        viewModelScope.launch {
            try {
                when (val walkResult = fetchCompleteRoute(s, e, "foot-walking")) {
                    is Result.Success -> {
                        val (dist, dur, points) = walkResult.data
                        distance = dist
                        footTime = dur
                        polylinePoints = points

                        launch {
                            when (val bikeResult = repo.calculateRoute(s, e, "cycling")) {
                                is Result.Success -> bikeTime = bikeResult.data.second
                                else -> bikeTime = "N/A"
                            }
                        }
                    }
                    is Result.Error -> {
                        Log.e("ROUTE", "Error: ${walkResult.message}")
                    }
                    else -> {}
                }
            } finally {
                calculating = false
            }
        }
    }

    private suspend fun fetchCompleteRoute(
        start: LatLng,
        end: LatLng,
        profile: String
    ): Result<Triple<String, String, List<LatLng>>> {
        return try {
            val coordinates = listOf(
                listOf(start.longitude, start.latitude),
                listOf(end.longitude, end.latitude)
            )
            val request = ORSRequest(coordinates)
            val response = OpenRouteServiceInstance.api.getDirections(profile, request)

            val feature = response.features.firstOrNull()
                ?: return Result.Error("Aucune route trouvée")

            val summary = feature.properties?.summary
                ?: return Result.Error("Pas de résumé disponible")

            val distanceKm = if (summary.distance < 10000)
                String.format("%.1f", summary.distance / 1000)
            else
                (summary.distance / 1000).toInt().toString()

            val durationMin = (summary.duration / 60).toInt()
            val durationText = if (durationMin < 60) "$durationMin min"
            else "${durationMin / 60}h ${durationMin % 60}min"

            val points = feature.geometry.coordinates.map { coord ->
                LatLng(coord[1], coord[0])
            }

            Result.Success(Triple("$distanceKm km", durationText, points))
        } catch (e: Exception) {
            Log.e("ROUTE", "Error: ${e.message}", e)
            Result.Error("Erreur: ${e.message}")
        }
    }

    fun createAdventure(token: String, photoFile: File?) {
        viewModelScope.launch {
            createResult = Result.Loading

            val userId = JwtHelper.getUserIdFromToken(token) ?: run {
                createResult = Result.Error("⚠️ Invalid token")
                return@launch
            }

            // Extract distance and duration
            val distanceMeters = distance.replace(" km", "").replace(",", ".").toDoubleOrNull()?.times(1000) ?: 0.0
            val durationSeconds = when {
                activityType.contains("VELO") -> bikeTime
                else -> footTime
            }.let { time ->
                val parts = time.split(" ")
                var seconds = 0.0
                parts.forEach { part ->
                    when {
                        part.contains("h") -> seconds += part.replace("h", "").toDoubleOrNull()?.times(3600) ?: 0.0
                        part.contains("min") -> seconds += part.replace("min", "").toDoubleOrNull()?.times(60) ?: 0.0
                    }
                }
                seconds
            }

            val itineraire = Itineraire(
                pointDepart = Point(startLatLng!!.latitude, startLatLng!!.longitude),
                pointArrivee = Point(endLatLng!!.latitude, endLatLng!!.longitude),
                distance = distanceMeters,
                duree_estimee = durationSeconds
            )

            val campingData = if (includeCamping && campingName.isNotEmpty()) {
                CampingData(
                    nom = campingName,
                    lieu = campingLocation,
                    prix = campingPrice.toDoubleOrNull() ?: 0.0,
                    dateDebut = campingStart.ifEmpty { date },
                    dateFin = campingEnd
                )
            } else null

            Log.d("CREATE_ADVENTURE", "Creating sortie:")
            Log.d("CREATE_ADVENTURE", "Title: $title")
            Log.d("CREATE_ADVENTURE", "Type: $activityType")
            Log.d("CREATE_ADVENTURE", "Date: $date")
            Log.d("CREATE_ADVENTURE", "Distance: $distanceMeters m")
            Log.d("CREATE_ADVENTURE", "Duration: $durationSeconds s")
            Log.d("CREATE_ADVENTURE", "Option Camping: $includeCamping")
            if (campingData != null) {
                Log.d("CREATE_ADVENTURE", "Camping Data: Présent")
            }

            // ✅ FIX: Use 'repo' instead of 'repository'
            val result = repo.createSortie(
                token = token,
                createurId = userId,
                photoFile = photoFile,
                titre = title,
                description = description,
                date = date,
                type = activityType,
                optionCamping = includeCamping,
                lieu = startAddress.ifEmpty { "Non spécifié" },
                difficulte = "MOYEN",
                niveau = "INTERMEDIAIRE",
                capacite = capacity.toIntOrNull() ?: 10,
                prix = 0.0,
                itineraire = itineraire,
                camping = campingData
            )

            createResult = result
        }
    }

    fun resetForm() {
        title = ""
        description = ""
        date = ""
        activityType = ""
        capacity = ""
        includeCamping = false
        campingName = ""
        campingLocation = ""
        campingPrice = ""
        campingStart = ""
        campingEnd = ""
        startLatLng = null
        endLatLng = null
        startAddress = ""
        endAddress = ""
        distance = ""
        footTime = ""
        bikeTime = ""
        polylinePoints = emptyList()
        createResult = null
        editingStart = true
    }
}

package com.example.dam.viewmodel

import android.util.Log
import androidx.compose.runtime.getValue
